using System;
using UnityEngine;

namespace SousTension.Spikes.MovingFrame
{
    /// <summary>
    /// The 3D art the spike uses (Assets/_Project/Art/Prefabs): a list of named prefabs stored in Resources so that views can spawn them without
    /// referencing the art folders directly. Generated by the editor (PlayLocal.EnsureArtCatalog). When the catalog or an entry is missing the views
    /// fall back to their primitives, so the spike still runs without the art.
    /// </summary>
    public sealed class SpikeArtCatalog : ScriptableObject
    {
        [Serializable] public struct Entry { public string Key; public GameObject Prefab; }

        public Entry[] Entries = new Entry[0];

        public GameObject Get(string key)
        {
            for (int i = 0; i < Entries.Length; i++) if (Entries[i].Key == key) return Entries[i].Prefab;
            return null;
        }
    }
}
